// ============================================================
// CONFIGURE
// ============================================================
const CLASSIFICATION_FIELD = 'cf_classified'; // Custom field that marks ticket as already classified
// Set to null if you don't use a custom field; the workflow will
// re-classify every open ticket each run (idempotent if categories match).
// ============================================================

const raw = $input.first().json.data;
let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  return [{ json: { error: 'Failed to parse', raw } }];
}

const tickets = parsed.data || [];

// Filter to only unclassified tickets
const unclassified = tickets.filter(t => {
  if (CLASSIFICATION_FIELD) {
    return !t.cf || !t.cf[CLASSIFICATION_FIELD] || t.cf[CLASSIFICATION_FIELD] === 'false';
  }
  return !t.category; // fallback: no category assigned yet
});

if (unclassified.length === 0) {
  return [{ json: { message: 'No unclassified tickets', count: 0 } }];
}

return unclassified.map(t => ({
  json: {
    ticketId: t.id,
    ticketNumber: t.ticketNumber,
    subject: t.subject || '',
    description: (t.description || '').replace(/<[^>]*>/g, '').substring(0, 2000),
    channel: t.channel || 'unknown'
  }
}));

