// Parse OpenAI response and prepare Zoho Desk update payload
// ============================================================
// CONFIGURE: Map AI categories to your Zoho Desk values
// ============================================================
const CATEGORY_MAP = {
  'Billing': 'Billing',
  'Technical': 'Technical Support',
  'Sales': 'Sales Inquiry',
  'General': 'General',
  'Complaint': 'Complaint'
};

const DEPARTMENT_MAP = {
  'Support': 'YOUR_SUPPORT_DEPT_ID',
  'Sales': 'YOUR_SALES_DEPT_ID',
  'Billing': 'YOUR_BILLING_DEPT_ID',
  'Engineering': 'YOUR_ENGINEERING_DEPT_ID'
};

const ORG_ID = 'YOUR_ORG_ID';
// ============================================================

const ticket = $('Filter Unclassified').first().json;
const aiResponse = $input.first().json;

let classification;
try {
  const content = aiResponse.choices[0].message.content;
  classification = JSON.parse(content);
} catch (e) {
  return [{ json: { error: 'Failed to parse AI response', ticketId: ticket.ticketId } }];
}

const category = CATEGORY_MAP[classification.category] || classification.category;
const deptId = DEPARTMENT_MAP[classification.department] || null;

const updatePayload = {
  category: category,
  priority: classification.priority || 'Medium'
};

if (deptId) {
  updatePayload.departmentId = deptId;
}

return [{
  json: {
    ticketId: ticket.ticketId,
    ticketNumber: ticket.ticketNumber,
    orgId: ORG_ID,
    classification,
    updatePayload
  }
}];
